#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SettingsSyncSelectedProtocolMaterializationPlan {
    pub multiaddr_requests: Vec<SettingsSyncSelectedMultiaddrMaterializationRequest>,
    pub deferred_protocol_requests: Vec<SettingsSyncSelectedDeferredProtocolMaterializationRequest>,
    pub missing_endpoint_provider_ids: Vec<String>,
    pub fail_closed_provider_ids: Vec<String>,
}

impl SettingsSyncSelectedProtocolMaterializationPlan {
    pub fn materialization_targets(
        &self,
    ) -> Vec<SettingsSyncProtocolProviderMaterializationTarget> {
        self.multiaddr_requests
            .iter()
            .map(SettingsSyncSelectedMultiaddrMaterializationRequest::materialization_target)
            .chain(self.deferred_protocol_requests.iter().map(
                SettingsSyncSelectedDeferredProtocolMaterializationRequest::materialization_target,
            ))
            .collect()
    }

    pub fn multiaddr_routing_plans(&self) -> Vec<RoutingPlan> {
        self.multiaddr_requests
            .iter()
            .map(SettingsSyncSelectedMultiaddrMaterializationRequest::routing_plan)
            .collect()
    }

    pub fn deferred_protocol_batches(
        &self,
    ) -> Vec<SettingsSyncSelectedDeferredProtocolMaterializationBatch> {
        let mut batches = BTreeMap::<
            String,
            Vec<SettingsSyncSelectedDeferredProtocolMaterializationRequest>,
        >::new();
        for request in &self.deferred_protocol_requests {
            batches
                .entry(request.protocol.clone())
                .or_default()
                .push(request.clone());
        }

        batches
            .into_iter()
            .map(
                |(protocol, requests)| SettingsSyncSelectedDeferredProtocolMaterializationBatch {
                    protocol,
                    requests,
                },
            )
            .collect()
    }

    pub fn deferred_protocol_batch_count(&self) -> usize {
        self.deferred_protocol_batches().len()
    }

    pub fn protocol_request_count(&self) -> usize {
        self.multiaddr_requests.len() + self.deferred_protocol_requests.len()
    }

    pub fn missing_endpoint_provider_count(&self) -> usize {
        self.missing_endpoint_provider_ids.len()
    }

    pub fn fail_closed_provider_count(&self) -> usize {
        self.fail_closed_provider_ids.len()
    }

    pub fn requires_protocol_materializer(&self) -> bool {
        self.protocol_request_count() > 0
    }

    pub fn has_missing_endpoint(&self) -> bool {
        !self.missing_endpoint_provider_ids.is_empty()
    }

    pub fn has_fail_closed_endpoint(&self) -> bool {
        !self.fail_closed_provider_ids.is_empty()
    }

    pub fn ready_for_protocol_materialization(&self) -> bool {
        self.requires_protocol_materializer()
            && !self.has_missing_endpoint()
            && !self.has_fail_closed_endpoint()
    }
}

impl SettingsSyncSelectedEndpointMaterializationRequest {
    pub fn fixture_ready(&self) -> bool {
        self.endpoint_status == SettingsSyncStoredProviderEndpointStatus::InProcessFixture
    }

    pub fn pending_materialization(&self) -> bool {
        matches!(
            self.endpoint_status,
            SettingsSyncStoredProviderEndpointStatus::Missing
                | SettingsSyncStoredProviderEndpointStatus::Multiaddr
                | SettingsSyncStoredProviderEndpointStatus::DeferredProtocol
        )
    }

    pub fn fail_closed(&self) -> bool {
        self.endpoint_status == SettingsSyncStoredProviderEndpointStatus::Unsupported
    }

    pub fn parsed_multiaddr(&self) -> Option<Multiaddr> {
        if self.endpoint_status != SettingsSyncStoredProviderEndpointStatus::Multiaddr {
            return None;
        }
        self.endpoint_ref
            .as_deref()
            .and_then(|endpoint_ref| Multiaddr::parse(endpoint_ref).ok())
    }

    pub fn multiaddr_materialization_request(
        &self,
    ) -> Option<SettingsSyncSelectedMultiaddrMaterializationRequest> {
        self.parsed_multiaddr().map(|endpoint| {
            SettingsSyncSelectedMultiaddrMaterializationRequest {
                provider_id: self.provider_id.clone(),
                endpoint,
            }
        })
    }

    pub fn deferred_protocol_materialization_request(
        &self,
    ) -> Option<SettingsSyncSelectedDeferredProtocolMaterializationRequest> {
        if self.endpoint_status != SettingsSyncStoredProviderEndpointStatus::DeferredProtocol {
            return None;
        }
        self.endpoint_ref
            .as_deref()
            .and_then(parse_deferred_protocol_endpoint)
            .map(
                |endpoint| SettingsSyncSelectedDeferredProtocolMaterializationRequest {
                    provider_id: self.provider_id.clone(),
                    protocol: endpoint.protocol,
                    target: endpoint.target,
                },
            )
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SettingsSyncSelectedEndpointMaterializationPlan {
    pub requests: Vec<SettingsSyncSelectedEndpointMaterializationRequest>,
}

impl SettingsSyncSelectedEndpointMaterializationPlan {
    pub fn new(requests: Vec<SettingsSyncSelectedEndpointMaterializationRequest>) -> Self {
        Self { requests }
    }

    pub fn request_count(&self) -> usize {
        self.requests.len()
    }

    pub fn fixture_ready_requests(
        &self,
    ) -> Vec<SettingsSyncSelectedEndpointMaterializationRequest> {
        self.requests
            .iter()
            .filter(|request| request.fixture_ready())
            .cloned()
            .collect()
    }

    pub fn fixture_ready_request_count(&self) -> usize {
        self.requests
            .iter()
            .filter(|request| request.fixture_ready())
            .count()
    }

    pub fn fixture_ready_provider_ids(&self) -> Vec<String> {
        self.requests
            .iter()
            .filter(|request| request.fixture_ready())
            .map(|request| request.provider_id.clone())
            .collect()
    }

    pub fn pending_requests(&self) -> Vec<SettingsSyncSelectedEndpointMaterializationRequest> {
        self.requests
            .iter()
            .filter(|request| request.pending_materialization())
            .cloned()
            .collect()
    }

    pub fn pending_request_count(&self) -> usize {
        self.requests
            .iter()
            .filter(|request| request.pending_materialization())
            .count()
    }

    pub fn pending_provider_ids(&self) -> Vec<String> {
        self.requests
            .iter()
            .filter(|request| request.pending_materialization())
            .map(|request| request.provider_id.clone())
            .collect()
    }

    pub fn multiaddr_requests(&self) -> Vec<SettingsSyncSelectedMultiaddrMaterializationRequest> {
        self.requests
            .iter()
            .filter_map(|request| request.multiaddr_materialization_request())
            .collect()
    }

    pub fn multiaddr_request_count(&self) -> usize {
        self.multiaddr_requests().len()
    }

    pub fn multiaddr_provider_ids(&self) -> Vec<String> {
        self.multiaddr_requests()
            .into_iter()
            .map(|request| request.provider_id)
            .collect()
    }

    pub fn deferred_protocol_requests(
        &self,
    ) -> Vec<SettingsSyncSelectedDeferredProtocolMaterializationRequest> {
        self.requests
            .iter()
            .filter_map(|request| request.deferred_protocol_materialization_request())
            .collect()
    }

    pub fn deferred_protocol_request_count(&self) -> usize {
        self.deferred_protocol_requests().len()
    }

    pub fn deferred_protocol_provider_ids(&self) -> Vec<String> {
        self.deferred_protocol_requests()
            .into_iter()
            .map(|request| request.provider_id)
            .collect()
    }

    pub fn fail_closed_requests(&self) -> Vec<SettingsSyncSelectedEndpointMaterializationRequest> {
        self.requests
            .iter()
            .filter(|request| request.fail_closed())
            .cloned()
            .collect()
    }

    pub fn fail_closed_request_count(&self) -> usize {
        self.requests
            .iter()
            .filter(|request| request.fail_closed())
            .count()
    }

    pub fn fail_closed_provider_ids(&self) -> Vec<String> {
        self.requests
            .iter()
            .filter(|request| request.fail_closed())
            .map(|request| request.provider_id.clone())
            .collect()
    }

    pub fn materialization_issues(&self) -> Vec<SettingsSyncSelectedEndpointMaterializationIssue> {
        let mut issues = Vec::with_capacity(self.materialization_issue_count());
        for request in &self.requests {
            let kind = match request.endpoint_status {
                SettingsSyncStoredProviderEndpointStatus::Missing => {
                    SettingsSyncSelectedEndpointMaterializationIssueKind::MissingEndpoint
                }
                SettingsSyncStoredProviderEndpointStatus::Unsupported => {
                    SettingsSyncSelectedEndpointMaterializationIssueKind::UnsupportedEndpoint
                }
                SettingsSyncStoredProviderEndpointStatus::InProcessFixture
                | SettingsSyncStoredProviderEndpointStatus::Multiaddr
                | SettingsSyncStoredProviderEndpointStatus::DeferredProtocol => continue,
            };
            issues.push(SettingsSyncSelectedEndpointMaterializationIssue {
                provider_id: request.provider_id.clone(),
                kind,
            });
        }
        issues
    }

    pub fn materialization_issue_count(&self) -> usize {
        self.requests
            .iter()
            .filter(|request| {
                matches!(
                    request.endpoint_status,
                    SettingsSyncStoredProviderEndpointStatus::Missing
                        | SettingsSyncStoredProviderEndpointStatus::Unsupported
                )
            })
            .count()
    }

    pub fn has_materialization_issue(&self) -> bool {
        self.materialization_issue_count() > 0
    }

    pub fn requires_protocol_materializer(&self) -> bool {
        self.requests
            .iter()
            .any(|request| request.pending_materialization())
    }

    pub fn protocol_materialization_plan(&self) -> SettingsSyncSelectedProtocolMaterializationPlan {
        SettingsSyncSelectedProtocolMaterializationPlan {
            multiaddr_requests: self.multiaddr_requests(),
            deferred_protocol_requests: self.deferred_protocol_requests(),
            missing_endpoint_provider_ids: self
                .requests
                .iter()
                .filter(|request| {
                    request.endpoint_status == SettingsSyncStoredProviderEndpointStatus::Missing
                })
                .map(|request| request.provider_id.clone())
                .collect(),
            fail_closed_provider_ids: self.fail_closed_provider_ids(),
        }
    }

    pub fn has_fail_closed_request(&self) -> bool {
        self.requests.iter().any(|request| request.fail_closed())
    }

    pub fn ready_for_fixture_materialization_only(&self) -> bool {
        !self.requires_protocol_materializer() && !self.has_fail_closed_request()
    }
}

