#[cfg(feature = "local-preview-fixtures")]
fn local_settings_sync_preview_discovery_summary(
    database: &SlateProfileDatabase,
    profile: &str,
    sync_secret: &SlateSyncSecret,
    preparation: &LocalSettingsSyncFixturePreparation,
    config: &SettingsSyncSchedulerConfig,
    device_daemon: &dyn BroadwebdClient,
    provider_daemon: &dyn BroadwebdClient,
) -> Result<LocalSettingsSyncDiscoverySummary, LocalSettingsSyncPreviewError> {
    let discovery_network = SimulatedProfileSyncPeerDiscoveryNetwork::new();
    let discovery_provider = discovery_network.provider();
    let provider_signer = sync_secret.derive_profile_sync_device_signer(
        profile,
        DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_ID,
        DEFAULT_PROFILE_SYNC_MEMBERSHIP_EPOCH,
    )?;
    let advertisement = sign_profile_sync_peer_advertisement(
        ProfileSyncPeerAdvertisement::new(
            LOCAL_SETTINGS_SYNC_PREVIEW_NETWORK_ID,
            provider_signer.device_id(),
            DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_ID,
            LOCAL_SETTINGS_SYNC_PREVIEW_DISCOVERY_SERVICE_ADDR,
            1,
        )?,
        &provider_signer,
    )?;
    discovery_provider.publish_profile_sync_peer(
        ProfileSyncPeerDiscoveryProtocol::LocalSimulation,
        DEFAULT_PROFILE_SYNC_DISCOVERY_NAMESPACE,
        advertisement,
    )?;
    let discovery_query = ProfileSyncPeerDiscoveryQuery::for_default_namespace(
        LOCAL_SETTINGS_SYNC_PREVIEW_NETWORK_ID,
        preparation.local_device_id.as_str(),
        [ProfileSyncPeerDiscoveryProtocol::LocalSimulation],
        8,
    )?;
    let retention_provider_handles = [SettingsSyncRetentionProviderHandle::with_endpoint_ref(
        DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_ID,
        preparation.provider_endpoint_ref.as_str(),
        provider_daemon,
    )];
    let plan = BroadwebdSettingsSyncScheduler::new(device_daemon)
        .plan_once_discovering_trusted_retention_providers(
            database,
            config,
            &preparation.signer,
            &discovery_provider,
            &discovery_query,
            &retention_provider_handles,
        )?;

    Ok(LocalSettingsSyncDiscoverySummary {
        trusted_peer_count: plan.trusted_peer_count(),
        rejected_peer_count: plan.rejected_peer_count(),
        selected_retention_provider_count: plan.selected_retention_provider_count(),
        retention_provider_selection_issue_count: plan
            .cycle
            .retention_provider_selection_issue_count(),
        rejections: local_settings_sync_discovery_rejection_summaries(&plan.discovery_report),
    })
}

#[cfg(feature = "local-preview-fixtures")]
fn run_local_settings_sync_fixture_cycle(
    database: &SlateProfileDatabase,
    profile: &str,
    sync_secret: &SlateSyncSecret,
    state_root_parent: impl Into<PathBuf>,
    preparation: LocalSettingsSyncFixturePreparation,
) -> Result<LocalSettingsSyncFixtureCycleSummary, LocalSettingsSyncPreviewError> {
    let state_root = LocalSettingsSyncPreviewStateRoot::prepare(state_root_parent)?;
    let fixture = LocalProfileSyncFixture::new();
    let mut device_registry = PluginRegistry::new();
    device_registry
        .register_service(fixture.service_for_device(preparation.local_device_id.as_str()));
    let mut provider_registry = PluginRegistry::new();
    provider_registry.register_service(fixture.service_for_provider_with_roles(
        DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_ID,
        DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_KIND,
        ProfileSyncProviderRoles::availability_provider(),
    ));

    let budget = ResourceBudget::default();
    let device_daemon = BroadwebDaemon::start_with_registry(
        state_root.device_state_root(),
        budget.clone(),
        device_registry,
    )?;
    let provider_daemon = BroadwebDaemon::start_with_registry(
        state_root.provider_state_root(),
        budget,
        provider_registry,
    )?;
    let provider_daemons = [SettingsSyncInProcessFixtureProviderDaemon::new(
        DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_ID,
        LOCAL_SETTINGS_SYNC_PREVIEW_NETWORK_ID,
        &provider_daemon,
    )];
    let policy = SettingsSyncCyclePolicy::new(ProfileSyncRetentionPolicy::default(), 4, 8, 1);
    let config = SettingsSyncSchedulerConfig::new(
        profile,
        LOCAL_SETTINGS_SYNC_PREVIEW_ROOT_ID,
        policy.clone(),
    );
    let discovery_summary = local_settings_sync_preview_discovery_summary(
        database,
        profile,
        sync_secret,
        &preparation,
        &config,
        &device_daemon,
        &provider_daemon,
    )?;
    let run = BroadwebdSettingsSyncScheduler::new(&device_daemon)
        .run_once_with_membership_log_and_stored_in_process_fixture_retention_provider_daemons_and_sync_secret(
            database,
            &config,
            PROFILE_SYNC_MEMBERSHIP_LOG_ROOT_ID,
            sync_secret,
            &preparation.signer,
            4,
            &provider_daemons,
        )?;
    let after_health = BroadwebdSettingsSyncRunner::new(&device_daemon).settings_sync_health(
        database,
        profile,
        LOCAL_SETTINGS_SYNC_PREVIEW_ROOT_ID,
        config.policy.minimum_online_retaining_providers,
    )?;
    let readiness = database.profile_sync_local_readiness(profile)?;
    let published_object_count = run.run.cycle.cycle.published_object_ids().len();
    let root_object_provider_issues =
        local_settings_sync_root_object_provider_issue_summaries(&after_health);
    let retention_provider_selection_issues =
        local_settings_sync_retention_provider_selection_issue_summaries(
            run.retention_provider_selection_issues(),
        );
    let stored_provider_metadata_issues =
        local_settings_sync_stored_provider_metadata_issue_summaries(
            run.stored_provider_metadata_issues(),
        );
    let retention_issues =
        local_settings_sync_retention_issue_summaries(run.run.cycle.retention_issues());
    let endpoint_plan = run
        .run
        .stored_provider_plan
        .selected_endpoint_materialization_plan();
    let protocol_plan = endpoint_plan.protocol_materialization_plan();

    Ok(LocalSettingsSyncFixtureCycleSummary {
        profile: profile.to_string(),
        local_device_id: preparation.local_device_id,
        provider_id: DEFAULT_PROFILE_SYNC_PREVIEW_PROVIDER_ID.to_string(),
        provider_endpoint_ref: preparation.provider_endpoint_ref,
        ready_for_manual_sync: readiness.ready_for_manual_sync,
        blocked_reason: readiness.blocked_reason,
        pulled_membership_application_count: run.pulled_membership_application_count(),
        discovery_trusted_peer_count: discovery_summary.trusted_peer_count,
        discovery_rejected_peer_count: discovery_summary.rejected_peer_count,
        discovery_selected_retention_provider_count: discovery_summary
            .selected_retention_provider_count,
        discovery_retention_provider_selection_issue_count: discovery_summary
            .retention_provider_selection_issue_count,
        discovery_rejections: discovery_summary.rejections,
        selected_retention_provider_count: run.selected_retention_provider_count(),
        materialized_retention_provider_count: run.materialized_retention_provider_count(),
        retained_provider_count: run.retained_provider_count(),
        published_step_count: run.run.cycle.cycle.cycle.published_step_count(),
        published_object_count,
        retained_object_count: run.run.cycle.retained_object_ids.len(),
        retention_issue_count: retention_issues.len(),
        retention_issues,
        fixture_materialization_issue_count: run.fixture_materialization_issue_count(),
        retention_provider_selection_issue_count: retention_provider_selection_issues.len(),
        retention_provider_selection_issues,
        stored_provider_metadata_issue_count: stored_provider_metadata_issues.len(),
        stored_provider_metadata_issues,
        all_fixture_providers_materialized: run.all_fixture_providers_materialized(),
        selected_endpoint_ready_provider_count: endpoint_plan.fixture_ready_request_count(),
        selected_endpoint_pending_protocol_provider_count: protocol_plan.protocol_request_count(),
        selected_endpoint_missing_provider_count: protocol_plan.missing_endpoint_provider_count(),
        selected_endpoint_fail_closed_provider_count: protocol_plan.fail_closed_provider_count(),
        selected_endpoint_requires_protocol_materializer: protocol_plan
            .requires_protocol_materializer(),
        degraded_before: run.run.preflight.preflight.before_health.degraded(),
        degraded_after: after_health.degraded(),
        root_object_provider_issue_count: root_object_provider_issues.len(),
        root_object_provider_issues,
    })
}

